@@ -0,0 +1,97 @@
+package inboxmail
+
+import (
+	"strings"
+	"testing"
+
+	"gorm.io/gorm"
+)
+
+func seedUserData(t *testing.T, tx *gorm.DB, userID uint64) (DeliveryEntity, ClaimEntity) {
+	t.Helper()
+	delivery := createDelivery(t, tx, userID, CampaignDedupeKey(userID, 1, userID))
+	claim := ClaimEntity{
+		DeliveryId: delivery.Id, AttachmentId: 5, UserId: userID, CampaignId: 1,
+		Handler: "badge", SourceKey: ClaimSourceKey(delivery.Id, 5),
+		Status: ClaimStatusGranted,
+	}
+	if err := tx.Create(&claim).Error; err != nil {
+		t.Fatalf("create claim: %v", err)
+	}
+	return delivery, claim
+}
+
+func TestDeleteUserDataRemovesOnlyTargetUser(t *testing.T) {
+	tx := openTestDB(t)
+	targetDelivery, targetClaim := seedUserData(t, tx, 21)
+	otherDelivery, otherClaim := seedUserData(t, tx, 22)
+
+	if err := DeleteUserDataTx(tx, 21); err != nil {
+		t.Fatalf("DeleteUserDataTx: %v", err)
+	}
+	var deliveryCount, claimCount int64
+	if err := tx.Model(&DeliveryEntity{}).Where("id = ?", targetDelivery.Id).Count(&deliveryCount).Error; err != nil {
+		t.Fatalf("count target delivery: %v", err)
+	}
+	if err := tx.Model(&ClaimEntity{}).Where("id = ?", targetClaim.Id).Count(&claimCount).Error; err != nil {
+		t.Fatalf("count target claim: %v", err)
+	}
+	if deliveryCount != 0 || claimCount != 0 {
+		t.Fatalf("target user rows survive delete: deliveries=%d claims=%d", deliveryCount, claimCount)
+	}
+	if err := tx.Model(&DeliveryEntity{}).Where("id = ?", otherDelivery.Id).Count(&deliveryCount).Error; err != nil {
+		t.Fatalf("count other delivery: %v", err)
+	}
+	if err := tx.Model(&ClaimEntity{}).Where("id = ?", otherClaim.Id).Count(&claimCount).Error; err != nil {
+		t.Fatalf("count other claim: %v", err)
+	}
+	if deliveryCount != 1 || claimCount != 1 {
+		t.Fatalf("other user rows affected by delete: deliveries=%d claims=%d", deliveryCount, claimCount)
+	}
+	// 幂等：重复清理不留错误。
+	if err := DeleteUserDataTx(tx, 21); err != nil {
+		t.Fatalf("repeat DeleteUserDataTx: %v", err)
+	}
+}
+
+// 匿名化保留投递/领取事实行（Campaign 统计分母不变），只剥离用户身份并重建唯一键，
+// 供 user lifecycle 选择「保留聚合、移除个人关联」的清理策略。
+func TestAnonymizeUserDataKeepsAggregateRows(t *testing.T) {
+	tx := openTestDB(t)
+	delivery, claim := seedUserData(t, tx, 31)
+
+	if err := AnonymizeUserDataTx(tx, 31); err != nil {
+		t.Fatalf("AnonymizeUserDataTx: %v", err)
+	}
+	var storedDelivery DeliveryEntity
+	if err := tx.Where("id = ?", delivery.Id).Take(&storedDelivery).Error; err != nil {
+		t.Fatalf("anonymized delivery missing: %v", err)
+	}
+	if storedDelivery.UserId != AnonymizedUserID {
+		t.Fatalf("delivery user_id = %d, want %d", storedDelivery.UserId, AnonymizedUserID)
+	}
+	if !strings.HasPrefix(storedDelivery.DedupeKey, "anonymized:delivery:") {
+		t.Fatalf("delivery dedupe_key not rotated: %q", storedDelivery.DedupeKey)
+	}
+	var storedClaim ClaimEntity
+	if err := tx.Where("id = ?", claim.Id).Take(&storedClaim).Error; err != nil {
+		t.Fatalf("anonymized claim missing: %v", err)
+	}
+	if storedClaim.UserId != AnonymizedUserID {
+		t.Fatalf("claim user_id = %d, want %d", storedClaim.UserId, AnonymizedUserID)
+	}
+	if !strings.HasPrefix(storedClaim.SourceKey, "anonymized:claim:") {
+		t.Fatalf("claim source_key not rotated: %q", storedClaim.SourceKey)
+	}
+	// 幂等：二次匿名化不报错也不改变行数。
+	if err := AnonymizeUserDataTx(tx, 31); err != nil {
+		t.Fatalf("repeat AnonymizeUserDataTx: %v", err)
+	}
+	var deliveryCount int64
+	if err := tx.Model(&DeliveryEntity{}).Where("id = ?", delivery.Id).Count(&deliveryCount).Error; err != nil {
+		t.Fatalf("count anonymized delivery: %v", err)
+	}
+	if deliveryCount != 1 {
+		t.Fatalf("anonymized delivery count = %d, want 1", deliveryCount)
+	}
+}

diff --git a/apps/gooseforum/app/models/forum/inboxmail/message_version_repo.go b/apps/gooseforum/app/models/forum/inboxmail/message_version_repo.go
new file mode 100644
index 00000000..f5436317
--- /dev/null
+++ b/apps/gooseforum/app/models/forum/inboxmail/message_version_repo.go
@@ -0,0 +1,209 @@
+package inboxmail
+
+import (
+	"encoding/json"
+	"errors"
+	"fmt"
+	"strings"
+	"time"
+
+	"gorm.io/gorm"
+)
+
+var (
+	// ErrVersionNotFound 目标 Message Version 不存在。
+	ErrVersionNotFound = errors.New("inboxmail: message version not found")
+	// ErrPublishedVersionImmutable 已发布版本不可原地修改或删除。
+	ErrPublishedVersionImmutable = errors.New("inboxmail: published message version is immutable")
+	// ErrUnscopedVersionMutation 模型层更新缺少主键，无法确认目标行是否为草稿。
+	ErrUnscopedVersionMutation = errors.New("inboxmail: message version mutation requires a primary key")
+	// ErrDraftVersionRequired 操作只允许作用于草稿版本。
+	ErrDraftVersionRequired = errors.New("inboxmail: operation requires a draft message version")
+	// ErrMessageCodeRequired Message code 是 Trigger Registry 的稳定引用键，不能为空。
+	ErrMessageCodeRequired = errors.New("inboxmail: message code is required")
+)
+
+// CreateMessageTx 创建逻辑消息。code 全局唯一；重复 code 返回数据库唯一约束错误
+// （gorm.ErrDuplicatedKey），调用方据此做幂等创建。空 code 在此直接拒绝，
+// chk_inbox_message_code 作为绕过 Go 层写入的兜底。
+func CreateMessageTx(tx *gorm.DB, code, name string, createdBy uint64) (MessageEntity, error) {
+	code = strings.TrimSpace(code)
+	if code == "" {
+		return MessageEntity{}, ErrMessageCodeRequired
+	}
+	message := MessageEntity{
+		Code:      code,
+		Name:      name,
+		Status:    MessageStatusActive,
+		CreatedBy: createdBy,
+	}
+	if err := tx.Create(&message).Error; err != nil {
+		return MessageEntity{}, err
+	}
+	return message, nil
+}
+
+// CreateDraftVersionTx 为消息创建下一个版本的草稿（version_no = max+1）。
+// 并发创建相同版本号时数据库唯一索引会拒绝后到者，调用方需重试。
+func CreateDraftVersionTx(tx *gorm.DB, messageID uint64, content VersionContent, createdBy uint64) (MessageVersionEntity, error) {
+	if messageID == 0 {
+		return MessageVersionEntity{}, ErrVersionNotFound
+	}
+	versionNo, err := nextVersionNoTx(tx, messageID)
+	if err != nil {
+		return MessageVersionEntity{}, err
+	}
+	contentHash, err := HashVersionContent(content)
+	if err != nil {
+		return MessageVersionEntity{}, err
+	}
+	version := MessageVersionEntity{
+		MessageId:     messageID,
+		VersionNo:     versionNo,
+		Status:        StatusDraft,
+		Title:         content.Title,
+		Summary:       content.Summary,
+		BodyMarkdown:  content.BodyMarkdown,
+		Blocks:        content.Blocks,
+		SchemaVersion: normalizeSchemaVersion(content.SchemaVersion),
+		ContentHash:   contentHash,
+		CreatedBy:     createdBy,
+	}
+	if err := tx.Create(&version).Error; err != nil {
+		return MessageVersionEntity{}, err
+	}
+	return version, nil
+}
+
+// UpdateDraftContentTx 只更新草稿版本的内容。条件更新（WHERE status='draft'）
+// 是最后一道防线：目标已发布时返回 ErrPublishedVersionImmutable，不存在时返回
+// ErrVersionNotFound。
+func UpdateDraftContentTx(tx *gorm.DB, versionID uint64, content VersionContent) error {
+	contentHash, err := HashVersionContent(content)
+	if err != nil {
+		return err
+	}
+	// Blocks 必须先自行序列化：GORM 的 Updates(map) 不会对值应用 serializer:json，
+	// 直接传结构体会让两种方言的 json 列驱动报错（eventNotification 同款处理）。
+	blocks, err := json.Marshal(content.Blocks)
+	if err != nil {
+		return fmt.Errorf("inboxmail: marshal blocks: %w", err)
+	}
+	result := tx.Table(messageVersionTableName).
+		Where("id = ? AND status = ?", versionID, StatusDraft).
+		Updates(map[string]any{
+			"title":          content.Title,
+			"summary":        content.Summary,
+			"body_markdown":  content.BodyMarkdown,
+			"blocks":         blocks,
+			"schema_version": normalizeSchemaVersion(content.SchemaVersion),
+			"content_hash":   contentHash,
+			"updated_at":     time.Now(),
+		})
+	if result.Error != nil {
+		return result.Error
+	}
+	if result.RowsAffected == 0 {
+		return versionMutationError(tx, versionID)
+	}
+	return nil
+}
+
+// PublishVersionTx 把草稿发布为不可变版本：写入发布人、发布时间与重新计算的内容哈希。
+// 重复发布同一版本是幂等的（返回已发布行，不修改内容），Worker 重试与事件重放安全。
+func PublishVersionTx(tx *gorm.DB, versionID uint64, publishedBy uint64, publishedAt time.Time) (MessageVersionEntity, error) {
+	current, err := GetVersionByIDTx(tx, versionID)
+	if err != nil {
+		return MessageVersionEntity{}, err
+	}
+	if current.Status == StatusPublished {
+		return current, nil
+	}
+	if current.Status != StatusDraft {
+		return MessageVersionEntity{}, fmt.Errorf("%w: id=%d status=%s", ErrDraftVersionRequired, versionID, current.Status)
+	}
+	contentHash, err := HashVersionContent(current.Content())
+	if err != nil {
+		return MessageVersionEntity{}, err
+	}
+	if publishedAt.IsZero() {
+		publishedAt = time.Now()
+	}
+	result := tx.Table(messageVersionTableName).
+		Where("id = ? AND status = ?", versionID, StatusDraft).
+		Updates(map[string]any{
+			"status":       StatusPublished,
+			"content_hash": contentHash,
+			"published_at": publishedAt,
+			"published_by": publishedBy,
+			"updated_at":   time.Now(),
+		})
+	if result.Error != nil {
+		return MessageVersionEntity{}, result.Error
+	}
+	if result.RowsAffected == 0 {
+		// 并发发布：另一方已冻结该版本，返回其落库状态即为成功。
+		after, err := GetVersionByIDTx(tx, versionID)
+		if err != nil {
+			return MessageVersionEntity{}, err
+		}
+		if after.Status == StatusPublished {
+			return after, nil
+		}
+		return MessageVersionEntity{}, fmt.Errorf("%w: id=%d status=%s", ErrDraftVersionRequired, versionID, after.Status)
+	}
+	return GetVersionByIDTx(tx, versionID)
+}
+
+// GetVersionByIDTx 读取单个版本；不存在时返回 gorm.ErrRecordNotFound。
+func GetVersionByIDTx(tx *gorm.DB, versionID uint64) (MessageVersionEntity, error) {
+	var version MessageVersionEntity
+	if err := tx.Table(messageVersionTableName).Where("id = ?", versionID).Take(&version).Error; err != nil {
+		return MessageVersionEntity{}, err
+	}
+	return version, nil
+}
+
+// GetLatestPublishedVersionTx 返回消息的最新已发布版本（草稿修订不算）；
+// 不存在时返回 gorm.ErrRecordNotFound。
+func GetLatestPublishedVersionTx(tx *gorm.DB, messageID uint64) (MessageVersionEntity, error) {
+	var version MessageVersionEntity
+	err := tx.Table(messageVersionTableName).
+		Where("message_id = ? AND status = ?", messageID, StatusPublished).
+		Order("version_no DESC").
+		Take(&version).Error
+	if err != nil {
+		return MessageVersionEntity{}, err
+	}
+	return version, nil
+}
+
+func nextVersionNoTx(tx *gorm.DB, messageID uint64) (int, error) {
+	var row struct{ MaxNo int }
+	if err := tx.Table(messageVersionTableName).
+		Select("COALESCE(MAX(version_no), 0) AS max_no").
+		Where("message_id = ?", messageID).
+		Scan(&row).Error; err != nil {
+		return 0, err
+	}
+	return row.MaxNo + 1, nil
+}
+
+func versionMutationError(tx *gorm.DB, versionID uint64) error {
+	var persistedStatus string
+	if err := tx.Session(&gorm.Session{NewDB: true}).
+		Table(messageVersionTableName).
+		Where("id = ?", versionID).
+		Limit(1).
+		Pluck("status", &persistedStatus).Error; err != nil {
+		return err
+	}
+	switch persistedStatus {
+	case "":
+		return fmt.Errorf("%w: id=%d", ErrVersionNotFound, versionID)
+	case StatusPublished:
+		return fmt.Errorf("%w: id=%d", ErrPublishedVersionImmutable, versionID)
+	default:
+		return fmt.Errorf("%w: id=%d status=%s", ErrDraftVersionRequired, versionID, persistedStatus)
+	}
+}

diff --git a/apps/gooseforum/app/models/forum/inboxmail/message_version_test.go b/apps/gooseforum/app/models/forum/inboxmail/message_version_test.go
new file mode 100644
index 00000000..a17aaf14
--- /dev/null
+++ b/apps/gooseforum/app/models/forum/inboxmail/message_version_test.go
@@ -0,0 +1,285 @@
+package inboxmail
+
+import (
+	"encoding/json"
+	"errors"
+	"testing"
+	"time"
+
+	"gorm.io/gorm"
+)
+
+func testContent(body string) VersionContent {
+	return VersionContent{
+		Title:         "标题",
+		Summary:       "摘要",
+		BodyMarkdown:  body,
+		Blocks:        []Block{{Type: "badge", Payload: json.RawMessage(`{"badgeCode":"welcome_2026"}`)}},
+		SchemaVersion: 1,
+	}
+}
+
+func mustCreateMessage(t *testing.T, tx *gorm.DB, code string) MessageEntity {
+	t.Helper()
+	message, err := CreateMessageTx(tx, code, "测试消息", 1)
+	if err != nil {
+		t.Fatalf("CreateMessageTx(%q): %v", code, err)
+	}
+	return message
+}
+
+func mustCreateDraft(t *testing.T, tx *gorm.DB, messageID uint64, content VersionContent) MessageVersionEntity {
+	t.Helper()
+	version, err := CreateDraftVersionTx(tx, messageID, content, 1)
+	if err != nil {
+		t.Fatalf("CreateDraftVersionTx: %v", err)
+	}
+	return version
+}
+
+func mustPublish(t *testing.T, tx *gorm.DB, versionID uint64) MessageVersionEntity {
+	t.Helper()
+	published, err := PublishVersionTx(tx, versionID, 7, time.Date(2026, 9, 28, 10, 0, 0, 0, time.UTC))
+	if err != nil {
+		t.Fatalf("PublishVersionTx: %v", err)
+	}
+	return published
+}
+
+// 发布后的 Message Version 是投递历史的唯一内容源：任何路径都不得原地修改或删除，
+// 修订只能通过新建 version 行完成（epic #769 核心决策 3）。
+func TestPublishedVersionRejectsInPlaceMutation(t *testing.T) {
+	tx := openTestDB(t)
+	message := mustCreateMessage(t, tx, "security.password_missing")
+	draft := mustCreateDraft(t, tx, message.Id, testContent("draft body"))
+	published := mustPublish(t, tx, draft.Id)
+	if published.Status != StatusPublished || published.PublishedAt == nil || published.PublishedBy != 7 {
+		t.Fatalf("published row not frozen correctly: %#v", published)
+	}
+	wantHash, err := HashVersionContent(testContent("draft body"))
+	if err != nil {
+		t.Fatalf("HashVersionContent: %v", err)
+	}
+	if published.ContentHash != wantHash {
+		t.Fatalf("published content hash = %q, want %q", published.ContentHash, wantHash)
+	}
+
+	cases := []struct {
+		name string
+		run  func() error
+	}{
+		{
+			name: "repository draft update",
+			run: func() error {
+				return UpdateDraftContentTx(tx, published.Id, testContent("mutated body"))
+			},
+		},
+		{
+			name: "model map update",
+			run: func() error {
+				return tx.Model(&MessageVersionEntity{Id: published.Id}).
+					Updates(map[string]any{"body_markdown": "mutated"}).Error
+			},
+		},
+		{
+			name: "model single column update",
+			run: func() error {
+				return tx.Model(&MessageVersionEntity{Id: published.Id}).Update("title", "mutated").Error
+			},
+		},
+		{
+			name: "model save",
+			run: func() error {
+				loaded, err := GetVersionByIDTx(tx, published.Id)
+				if err != nil {
+					return err
+				}
+				loaded.BodyMarkdown = "mutated"
+				return tx.Save(&loaded).Error
+			},
+		},
+		{
+			name: "model delete",
+			run: func() error {
+				return tx.Where("id = ?", published.Id).Delete(&MessageVersionEntity{Id: published.Id}).Error
+			},
+		},
+	}
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			if err := tc.run(); !errors.Is(err, ErrPublishedVersionImmutable) {
+				t.Fatalf("mutation error = %v, want ErrPublishedVersionImmutable", err)
+			}
+		})
+	}
+
+	stored, err := GetVersionByIDTx(tx, published.Id)
+	if err != nil {
+		t.Fatalf("reload published version: %v", err)
+	}
+	if stored.BodyMarkdown != "draft body" || stored.ContentHash != wantHash || stored.Status != StatusPublished {
+		t.Fatalf("published row was mutated: %#v", stored)
+	}
+
+	// 重复发布必须幂等：Worker 重试/事件重放不得改变已发布内容。
+	again, err := PublishVersionTx(tx, published.Id, 99, time.Now())
+	if err != nil {
+		t.Fatalf("idempotent publish: %v", err)
+	}
+	if again.ContentHash != wantHash || again.PublishedBy != 7 {
+		t.Fatalf("re-publish changed published row: %#v", again)
+	}
+}
+
+// 模型层必须拒绝无法定位目标行的批量更新：hook 无法确认目标是否为草稿时，
+// 宁可拒绝也不能冒改写已发布历史的风险。
+func TestVersionMutationWithoutPrimaryKeyIsRefused(t *testing.T) {
+	tx := openTestDB(t)
+	message := mustCreateMessage(t, tx, "security.scoped")
+	draft := mustCreateDraft(t, tx, message.Id, testContent("body"))
+
+	err := tx.Model(&MessageVersionEntity{}).Where("id = ?", draft.Id).Update("title", "mutated").Error
+	if !errors.Is(err, ErrUnscopedVersionMutation) {
+		t.Fatalf("unscoped update error = %v, want ErrUnscopedVersionMutation", err)
+	}
+}
+
+func TestDraftVersionRemainsEditable(t *testing.T) {
+	tx := openTestDB(t)
+	message := mustCreateMessage(t, tx, "security.draft_edit")
+	draft := mustCreateDraft(t, tx, message.Id, testContent("first body"))
+
+	updated := testContent("second body")
+	if err := UpdateDraftContentTx(tx, draft.Id, updated); err != nil {
+		t.Fatalf("UpdateDraftContentTx: %v", err)
+	}
+	stored, err := GetVersionByIDTx(tx, draft.Id)
+	if err != nil {
+		t.Fatalf("reload draft: %v", err)
+	}
+	if stored.BodyMarkdown != "second body" || stored.Status != StatusDraft {
+		t.Fatalf("draft not updated: %#v", stored)
+	}
+	wantHash, err := HashVersionContent(updated)
+	if err != nil {
+		t.Fatalf("HashVersionContent: %v", err)
+	}
+	if stored.ContentHash != wantHash {
+		t.Fatalf("draft content hash = %q, want %q", stored.ContentHash, wantHash)
+	}
+}
+
+func TestRevisionCreatesNewVersionRow(t *testing.T) {
+	tx := openTestDB(t)
+	message := mustCreateMessage(t, tx, "activity.welcome")
+	first := mustCreateDraft(t, tx, message.Id, testContent("v1 body"))
+	publishedFirst := mustPublish(t, tx, first.Id)
+
+	second := mustCreateDraft(t, tx, message.Id, testContent("v2 body"))
+	if second.VersionNo != publishedFirst.VersionNo+1 {
+		t.Fatalf("revision version_no = %d, want %d", second.VersionNo, publishedFirst.VersionNo+1)
+	}
+
+	// 列表/投递默认读取最新已发布版本，草稿修订不得改变它。
+	latest, err := GetLatestPublishedVersionTx(tx, message.Id)
+	if err != nil {
+		t.Fatalf("GetLatestPublishedVersionTx: %v", err)
+	}
+	if latest.Id != publishedFirst.Id || latest.BodyMarkdown != "v1 body" {
+		t.Fatalf("latest published version = %#v, want %#v", latest, publishedFirst)
+	}
+	if _, err := GetLatestPublishedVersionTx(tx, message.Id+999); !errors.Is(err, gorm.ErrRecordNotFound) {
+		t.Fatalf("missing message error = %v, want gorm.ErrRecordNotFound", err)
+	}
+}
+
+func TestCreateDraftVersionStampsContentHashAndSequence(t *testing.T) {
+	tx := openTestDB(t)
+	message := mustCreateMessage(t, tx, "system.maintenance")
+	first := mustCreateDraft(t, tx, message.Id, testContent("body"))
+	wantHash, err := HashVersionContent(testContent("body"))
+	if err != nil {
+		t.Fatalf("HashVersionContent: %v", err)
+	}
+	if first.VersionNo != 1 || first.ContentHash != wantHash || first.Status != StatusDraft || first.MessageId != message.Id {
+		t.Fatalf("draft row = %#v", first)
+	}
+	if err := tx.Create(&MessageVersionEntity{MessageId: message.Id, VersionNo: first.VersionNo}).Error; !errors.Is(err, gorm.ErrDuplicatedKey) {
+		t.Fatalf("duplicate (message_id, version_no) error = %v, want gorm.ErrDuplicatedKey", err)
+	}
+}
+
+// 内容哈希必须对语义相同的内容稳定：Block payload 的 JSON key 顺序不同
+// （由不同序列化路径产生）不得改变哈希，否则幂等判断会误判为内容变更。
+func TestHashVersionContentIsCanonical(t *testing.T) {
+	left := VersionContent{
+		Title:        "t",
+		BodyMarkdown: "b",
+		Blocks:       []Block{{Type: "badge", Payload: json.RawMessage(`{"b":1,"a":{"d":2,"c":3}}`)}},
+	}
+	right := VersionContent{
+		Title:        "t",
+		BodyMarkdown: "b",
+		Blocks:       []Block{{Type: "badge", Payload: json.RawMessage(`{"a":{"c":3,"d":2},"b":1}`)}},
+	}
+	leftHash, err := HashVersionContent(left)
+	if err != nil {
+		t.Fatalf("HashVersionContent(left): %v", err)
+	}
+	rightHash, err := HashVersionContent(right)
+	if err != nil {
+		t.Fatalf("HashVersionContent(right): %v", err)
+	}
+	if leftHash != rightHash {
+		t.Fatalf("canonical hashes differ: %q vs %q", leftHash, rightHash)
+	}
+
+	changed := left
+	changed.BodyMarkdown = "b2"
+	changedHash, err := HashVersionContent(changed)
+	if err != nil {
+		t.Fatalf("HashVersionContent(changed): %v", err)
+	}
+	if changedHash == leftHash {
+		t.Fatal("content change did not change the hash")
+	}
+
+	// 大整数必须保留精度：float64 解码会让这两个不同 id 产生同一哈希。
+	bigInt := VersionContent{Blocks: []Block{{Type: "badge", Payload: json.RawMessage(`{"badgeId":9007199254740993}`)}}}
+	smallerInt := VersionContent{Blocks: []Block{{Type: "badge", Payload: json.RawMessage(`{"badgeId":9007199254740992}`)}}}
+	bigHash, err := HashVersionContent(bigInt)
+	if err != nil {
+		t.Fatalf("HashVersionContent(bigInt): %v", err)
+	}
+	smallerHash, err := HashVersionContent(smallerInt)
+	if err != nil {
+		t.Fatalf("HashVersionContent(smallerInt): %v", err)
+	}
+	if bigHash == smallerHash {
+		t.Fatal("large integer precision lost in content hash")
+	}
+}
+
+// Block payload 在 JSON 值之后带尾随数据时必须拒绝：Decode 只读单个值，
+// 不校验会让 {"a":1}junk 按 {"a":1} 参与哈希，而库存 RawMessage 仍含 junk，
+// 哈希与事实内容不再一致。
+func TestHashVersionContentRejectsTrailingGarbage(t *testing.T) {
+	for _, payload := range []string{
+		`{"a":1}junk`,
+		`{"a":1} {"b":2}`,
+		`{"a":1}"`,
+	} {
+		_, err := HashVersionContent(VersionContent{
+			Blocks: []Block{{Type: "badge", Payload: json.RawMessage(payload)}},
+		})
+		if err == nil {
+			t.Fatalf("payload %q with trailing data was accepted", payload)
+		}
+	}
+	// 值后的空白属于合法 JSON，必须仍然通过。
+	if _, err := HashVersionContent(VersionContent{
+		Blocks: []Block{{Type: "badge", Payload: json.RawMessage("{\"a\":1}\n")}},
+	}); err != nil {
+		t.Fatalf("trailing whitespace rejected: %v", err)
+	}
+}

diff --git a/apps/gooseforum/app/models/forum/inboxmail/schema_test.go b/apps/gooseforum/app/models/forum/inboxmail/schema_test.go
new file mode 100644
index 00000000..3e1c2f93
--- /dev/null
+++ b/apps/gooseforum/app/models/forum/inboxmail/schema_test.go
@@ -0,0 +1,212 @@
+package inboxmail
+
+import (
+	"errors"
+	"testing"
+
+	"gorm.io/gorm"
+)
+
+// 新建库必须一次迁移出全部 7 张表；表名是后续 19 个子 issue 的共享契约。
+func TestAllModelsMigrateOnSQLite(t *testing.T) {
+	tx := openTestDB(t)
+	for _, table := range []string{
+		"inbox_message",
+		"inbox_message_version",
+		"inbox_campaign",
+		"inbox_campaign_attachment",
+		"inbox_campaign_run",
+		"inbox_delivery",
+		"inbox_claim",
+	} {
+		if !tx.Migrator().HasTable(table) {
+			t.Fatalf("table %s missing after AutoMigrate", table)
+		}
+	}
+}
+
+// 核心列表查询（信箱游标分页 / 未读 / 归档 / 待领取 / popup 候选 / campaign 维度）
+// 依赖这些索引；改索引名或列序会静默拖垮线上列表。
+func TestCoreListIndexesExist(t *testing.T) {
+	tx := openTestDB(t)
+	assertIndexColumns(t, tx, &DeliveryEntity{}, "idx_inbox_delivery_user_id", []string{"user_id", "id"})
+	assertIndexColumns(t, tx, &DeliveryEntity{}, "idx_inbox_delivery_user_read_id", []string{"user_id", "is_read", "id"})
+	assertIndexColumns(t, tx, &DeliveryEntity{}, "idx_inbox_delivery_user_archived_id", []string{"user_id", "is_archived", "id"})
+	assertIndexColumns(t, tx, &DeliveryEntity{}, "idx_inbox_delivery_user_claim_id", []string{"user_id", "claim_state", "id"})
+	assertIndexColumns(t, tx, &DeliveryEntity{}, "idx_inbox_delivery_user_popup_id", []string{"user_id", "popup_state", "id"})
+	assertIndexColumns(t, tx, &DeliveryEntity{}, "idx_inbox_delivery_campaign_status", []string{"campaign_id", "status"})
+	assertIndexColumns(t, tx, &ClaimEntity{}, "idx_inbox_claim_user_id", []string{"user_id", "id"})
+	assertIndexColumns(t, tx, &ClaimEntity{}, "idx_inbox_claim_campaign", []string{"campaign_id"})
+	assertIndexColumns(t, tx, &ClaimEntity{}, "idx_inbox_claim_status", []string{"status"})
+	assertIndexColumns(t, tx, &CampaignRunEntity{}, "idx_inbox_campaign_run_status", []string{"status", "id"})
+}
+
+func createDelivery(t *testing.T, tx *gorm.DB, userID uint64, dedupeKey string) DeliveryEntity {
+	t.Helper()
+	delivery := DeliveryEntity{
+		UserId:           userID,
+		MessageId:        1,
+		MessageVersionId: 1,
+		CampaignId:       1,
+		DedupeKey:        dedupeKey,
+		Status:           DeliveryStatusDelivered,
+		PopupState:       PopupStatePending,
+		ClaimState:       ClaimStateNone,
+	}
+	if err := tx.Create(&delivery).Error; err != nil {
+		t.Fatalf("create delivery: %v", err)
+	}
+	return delivery
+}
+
+// dedupe_key / source_key / (delivery_id, attachment_id) 必须由数据库唯一约束兜底：
+// Worker 重试、事件重放、双端并发领取都依赖这三个约束（epic #769 验收标准）。
+func TestUniqueConstraintsRejectDuplicates(t *testing.T) {
+	tx := openTestDB(t)
+
+	delivery := createDelivery(t, tx, 11, CampaignDedupeKey(1, 1, 11))
+	if err := tx.Create(&DeliveryEntity{
+		UserId: 11, MessageId: 1, MessageVersionId: 1, CampaignId: 1,
+		DedupeKey: CampaignDedupeKey(1, 1, 11), Status: DeliveryStatusDelivered,
+	}).Error; !errors.Is(err, gorm.ErrDuplicatedKey) {
+		t.Fatalf("duplicate dedupe_key error = %v, want gorm.ErrDuplicatedKey", err)
+	}
+
+	claim := ClaimEntity{
+		DeliveryId: delivery.Id, AttachmentId: 5, UserId: 11, CampaignId: 1,
+		Handler: "badge", SourceKey: ClaimSourceKey(delivery.Id, 5),
+		Status: ClaimStatusGranted,
+	}
+	if err := tx.Create(&claim).Error; err != nil {
+		t.Fatalf("create claim: %v", err)
+	}
+	// 同一 (delivery, attachment) 的第二次领取必须被拦下；用不同的字面 source_key
+	// 证明拦截者是 (delivery_id, attachment_id) 约束本身，而不是 source_key。
+	if err := tx.Create(&ClaimEntity{
+		DeliveryId: delivery.Id, AttachmentId: 5, UserId: 11, CampaignId: 1,
+		Handler: "badge", SourceKey: "probe:pair-constraint",
+		Status: ClaimStatusPending,
+	}).Error; !errors.Is(err, gorm.ErrDuplicatedKey) {
+		t.Fatalf("duplicate (delivery_id, attachment_id) error = %v, want gorm.ErrDuplicatedKey", err)
+	}
+	// 同一 source key 出现在不同 (delivery, attachment) 上必须被拦下（handler 层
+	// 幂等的最后防线，正常路径不会构造出该组合）。
+	if err := tx.Create(&ClaimEntity{
+		DeliveryId: delivery.Id, AttachmentId: 6, UserId: 11, CampaignId: 1,
+		Handler: "badge", SourceKey: claim.SourceKey, Status: ClaimStatusPending,
+	}).Error; !errors.Is(err, gorm.ErrDuplicatedKey) {
+		t.Fatalf("duplicate source_key error = %v, want gorm.ErrDuplicatedKey", err)
+	}
+}
+
+// #775 要求同一事件 occurrence 对不同 Campaign 各自成信：dedupe_key 是全局唯一索引，
+// 旧格式（缺 campaign 段）会让第二个 Campaign 的投递撞唯一索引，再被「重复=已投递」
+// 的幂等语义静默吞掉；同一 Campaign 内的事件重放仍必须被拦下。
+func TestTriggerDeliveriesForTwoCampaignsBothPersist(t *testing.T) {
+	tx := openTestDB(t)
+	userID := uint64(77)
+	for _, campaignID := range []uint64{1, 2} {
+		delivery := DeliveryEntity{
+			UserId: userID, MessageId: 1, MessageVersionId: 1, CampaignId: campaignID,
+			SourceType: DeliverySourceTrigger, TriggerEvent: "user.registered", TriggerEventId: "evt-9",
+			DedupeKey: TriggerDedupeKey(campaignID, "user.registered", "evt-9", userID),
+			Status:    DeliveryStatusDelivered,
+		}
+		if err := tx.Create(&delivery).Error; err != nil {
+			t.Fatalf("campaign %d trigger delivery rejected: %v", campaignID, err)
+		}
+		replay := delivery
+		replay.Id = 0
+		if err := tx.Create(&replay).Error; !errors.Is(err, gorm.ErrDuplicatedKey) {
+			t.Fatalf("campaign %d replay error = %v, want gorm.ErrDuplicatedKey", campaignID, err)
+		}
+	}
+	var count int64
+	if err := tx.Model(&DeliveryEntity{}).
+		Where("user_id = ? AND source_type = ?", userID, DeliverySourceTrigger).
+		Count(&count).Error; err != nil {
+		t.Fatalf("count trigger deliveries: %v", err)
+	}
+	if count != 2 {
+		t.Fatalf("trigger deliveries = %d, want 2 (one per campaign)", count)
+	}
+}
+
+// #777 的发布校验只在 (campaign_id, attachment_key) 粒度上保证附件唯一，同一 badge
+// code 出现在两个附件行是合法的；同一 delivery 的两个附件必须能各自领取一行，
+// 否则第二个附件会被 source_key 唯一约束顶掉（#770 评审定位的领取粒度缺陷）。
+func TestSameDeliveryTwoAttachmentsAreBothClaimable(t *testing.T) {
+	tx := openTestDB(t)
+	delivery := createDelivery(t, tx, 11, CampaignDedupeKey(1, 1, 11))
+	for _, attachmentID := range []uint64{5, 6} {
+		if err := tx.Create(&ClaimEntity{
+			DeliveryId: delivery.Id, AttachmentId: attachmentID, UserId: 11, CampaignId: 1,
+			Handler: "badge", SourceKey: ClaimSourceKey(delivery.Id, attachmentID),
+			Status: ClaimStatusPending,
+		}).Error; err != nil {
+			t.Fatalf("claim of attachment %d rejected: %v", attachmentID, err)
+		}
+	}
+	var count int64
+	if err := tx.Model(&ClaimEntity{}).Where("delivery_id = ?", delivery.Id).Count(&count).Error; err != nil {
+		t.Fatalf("count claims: %v", err)
+	}
+	if count != 2 {
+		t.Fatalf("claims of one delivery = %d, want 2", count)
+	}
+}
+
+// 四个业务键都必须拒绝空串：GORM 会把 Go 字符串零值写进 INSERT，若只靠唯一索引，
+// 第一次漏传会静默写入，第二次才报 gorm.ErrDuplicatedKey——而本仓库把重复键当作
+// 「已创建」的幂等成功，收件人 B..N 会被静默跳过、运行却报告成功。CHECK 约束必须让
+// 空串立刻以非重复错误失败。
+func TestEmptyBusinessKeysRejectedOnSQLite(t *testing.T) {
+	tx := openTestDB(t)
+	cases := []struct {
+		name  string
+		model any
+	}{
+		{"inbox_delivery.dedupe_key", &DeliveryEntity{
+			UserId: 1, MessageId: 1, MessageVersionId: 1, CampaignId: 1, Status: DeliveryStatusDelivered}},
+		{"inbox_claim.source_key", &ClaimEntity{
