+	name := fmt.Sprintf("2026/10/01/ai-moderation-%d-%d.png", time.Now().UnixNano(), aiTestFileSeq.Add(1))
+	if _, err := filedata.SaveFile(ownerID, name, "image/png", buf.Bytes()); err != nil {
